// src/lib/mcp/tools/get-project.ts
var get_project_default = defineTool3({
  name: "get_project",
  title: "Consultar projeto",
  description: "Retorna a descri\xE7\xE3o completa, a fun\xE7\xE3o, as ferramentas e os links p\xFAblicos de um projeto do portf\xF3lio.",
  inputSchema: {
    projectId: z.string().trim().min(1).describe("Identificador do projeto retornado por list_projects.")
  },
  annotations: {
    readOnlyHint: true,
    idempotentHint: true,
    openWorldHint: false
  },
  handler: ({ projectId }) => {
    const project = portfolioProjects.find(({ id }) => id === projectId);
    if (!project) throw new ToolError(`Projeto n\xE3o encontrado: ${projectId}`);
    const result = {
      id: project.id,
      title: project.title,
      shortDescription: project.shortDescription,
      description: project.description,
      role: project.role,
      tools: project.tools,
      portfolioUrl: `https://rayssamartins.app/projeto/${project.id}`,
      behanceUrl: project.behanceUrl
    };
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      structuredContent: result
    };
  }
});

// src/lib/mcp/tools/list-projects.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@2.0.4";
import { z as z2 } from "npm:zod@^4.6.5";
var list_projects_default = defineTool4({
  name: "list_projects",
  title: "Listar projetos do portf\xF3lio",
  description: "Lista os projetos p\xFAblicos de Rayssa Martins e permite filtrar por t\xEDtulo, fun\xE7\xE3o ou ferramenta.",
  inputSchema: {
    search: z2.string().trim().optional().describe("Termo opcional para filtrar projetos por t\xEDtulo, fun\xE7\xE3o ou ferramenta.")
  },
  annotations: {
    readOnlyHint: true,
    idempotentHint: true,
    openWorldHint: false
  },
  handler: ({ search }) => {
    const normalizedSearch = search?.toLocaleLowerCase("pt-BR");
    const matches = portfolioProjects.filter((project) => {
      if (!normalizedSearch) return true;
      return [project.title, project.role, ...project.tools].join(" ").toLocaleLowerCase("pt-BR").includes(normalizedSearch);
    }).map(({ id, title, shortDescription, role, tools, behanceUrl }) => ({
      id,
      title,
      shortDescription,
      role,
      tools,
      portfolioUrl: `https://rayssamartins.app/projeto/${id}`,
      behanceUrl
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(matches, null, 2) }],
      structuredContent: { projects: matches, total: matches.length }
    };
  }
});

